package com.casystem.onboarding.service;
import com.casystem.onboarding.model.MailSettings;import com.casystem.onboarding.repository.MailSettingsRepository;import org.junit.jupiter.api.*;import org.springframework.mail.javamail.JavaMailSenderImpl;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class MailServiceTest{MailSettingsRepository repo;CryptoService crypto;JavaMailSenderImpl sender;MailService service;@BeforeEach void set(){repo=mock(MailSettingsRepository.class);crypto=mock(CryptoService.class);sender=mock(JavaMailSenderImpl.class);service=new MailService(repo,crypto,"http://localhost:5173"){@Override protected JavaMailSenderImpl sender(MailSettings s){return sender;}};}
 @Test void configuraSender587(){MailSettings s=settings();when(crypto.decrypt("enc")).thenReturn("clave");MailService real=new MailService(repo,crypto,"http://localhost");JavaMailSenderImpl m=real.sender(s);assertEquals("smtp.x.com",m.getHost());assertEquals(587,m.getPort());assertEquals("sender@x.com",m.getUsername());assertEquals("clave",m.getPassword());assertEquals("true",m.getJavaMailProperties().getProperty("mail.smtp.starttls.enable"));}
 @Test void configuraSender465Ssl(){MailSettings s=settings();s.setPort(465);when(crypto.decrypt("enc")).thenReturn("clave");MailService real=new MailService(repo,crypto,"http://localhost");JavaMailSenderImpl m=real.sender(s);assertEquals("true",m.getJavaMailProperties().getProperty("mail.smtp.ssl.enable"));assertEquals("false",m.getJavaMailProperties().getProperty("mail.smtp.starttls.enable"));}
 @Test void senderValidaCredenciales(){MailService real=new MailService(repo,crypto,"x");assertThrows(IllegalStateException.class,()->real.sender(new MailSettings()));}
 @Test void senderValidaHost(){MailSettings s=settings();s.setHost(" ");MailService real=new MailService(repo,crypto,"x");assertThrows(IllegalStateException.class,()->real.sender(s));}
 @Test void recoveryExigeConfiguracion(){when(repo.findById(1)).thenReturn(Optional.empty());assertThrows(IllegalStateException.class,()->service.recovery("a@b.com","t"));}
 @Test void recoveryEnviaMensaje(){MailSettings s=settings();when(repo.findById(1)).thenReturn(Optional.of(s));service.recovery("destino@x.com","abc");verify(sender).send(argThat((org.springframework.mail.SimpleMailMessage m)->m.getTo()[0].equals("destino@x.com")&&m.getText().contains("resetToken=abc")));}
 @Test void testEnviaMensaje(){service.test(settings(),"test@x.com");verify(sender).send(any(org.springframework.mail.SimpleMailMessage.class));}
 @Test void destinoEsObligatorio(){assertThrows(IllegalStateException.class,()->service.test(settings()," "));}
 @Test void errorSmtpSeTraduce(){doThrow(new RuntimeException("fallo smtp")).when(sender).send(any(org.springframework.mail.SimpleMailMessage.class));IllegalStateException e=assertThrows(IllegalStateException.class,()->service.test(settings(),"x@y.com"));assertTrue(e.getMessage().contains("No se pudo enviar"));}
 private MailSettings settings(){MailSettings s=new MailSettings();s.setSenderEmail("sender@x.com");s.setEncryptedPassword("enc");s.setHost("smtp.x.com");s.setPort(587);s.setAuth(true);s.setStarttls(true);return s;}}
